package engtelecom.poo;

import java.awt.image.ImagingOpException;
import java.lang.management.PlatformLoggingMXBean;
import java.util.ArrayList;

public class App {
    public static void main(String[] args) {

        ArrayList<Disciplina> materias = new ArrayList<>();

        materias.add(new Disciplina("Poo", new DiasDaSemana[]{DiasDaSemana.SEGUNDA,DiasDaSemana.QUINTA}));
        materias.add(new Disciplina("ELD2", new DiasDaSemana[]{DiasDaSemana.QUARTA,DiasDaSemana.TERCA}));
        materias.add(new Disciplina("eco",new DiasDaSemana[]{DiasDaSemana.TERCA,DiasDaSemana.SEXTA}));

        // variavel do tipo da colecao : colecao que vou percorrer
        for(Disciplina d : materias){
            // variavel do tipo da colecao : colecao que vou percorrer
           for(DiasDaSemana s : d.getDias()){
               if(s == DiasDaSemana.TERCA){
                   IO.println(d.getNome());
               }
           }
        }

        for (int i = 0; i < materias.size(); i++) {
            for (int j = 0; j < materias.get(i).getDias().length; j++) {
                if (materias.get(i).getDias()[j] == DiasDaSemana.TERCA){
                    IO.println(materias.get(i).getNome());
                }
            }
        }

        for (DiasDaSemana dd : DiasDaSemana.values()){
            IO.println(dd.extenso);
            for(Disciplina m : materias){
                for(DiasDaSemana a : m.getDias()){
                    if (a == dd){
                        IO.println(m.getNome());
                    }
                }
            }
        }


        for (int i = 1; i < Planeta.values().length+1; i++) {
            IO.println(Planeta.getByCodigo(i));
        }


    }
}
